import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
import { mkdtempSync, rmSync, writeFileSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { applyMemoryCommand } from "@chainlesschain/context-memory-kernel";
import { stateDigest } from "../src/lib/context-memory-kernel/durable-memory-port.js";
import { SegmentedMemoryPort } from "../src/lib/context-memory-kernel/segmented-memory-port.js";
import { createDurableMemoryFixture } from "../scripts/persistent-capacity-benchmark.mjs";

/**
 * Regression coverage for post-publish failure semantics in the segmented
 * memory authority ("Memory 发布后故障语义").
 *
 * The manifest publish sequence in `_publish` flips `published = true` only
 * after `renameSync(temporary, filePath)` succeeds. Any synchronous failure
 * raised *after* that rename (directory fsync, post-commit `_collect`) must
 * be surfaced as an error that declares `committed: true` and leaves the new
 * manifest readable on reopen, because the manifest is already authoritative.
 * Failures raised *before* the rename must NOT be declared committed and the
 * old state must remain intact.
 *
 * Synchronous failures are injected by replacing `fs.fsyncSync` with a stub
 * that throws on a targeted call, mirroring the production commit path where
 * `fsyncSync` runs inside the authority lock.
 */

const AT = "2026-09-13T00:00:00.000Z";
const CLOCK = () => Date.parse(AT);

let root;
let filePath;

beforeEach(() => {
  root = mkdtempSync(join(tmpdir(), "verify-22-"));
  filePath = join(root, "kernel-v1.json");
});

afterEach(() => {
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
  if (root) rmSync(root, { recursive: true, force: true });
});

function shardDirectory() {
  return join(root, "shards");
}

function seedEmptyAuthority() {
  const seeded = new SegmentedMemoryPort({ filePath });
  return seeded;
}

function seedAuthorityWith(recordCount) {
  const seeded = new SegmentedMemoryPort({ filePath });
  return seeded.importSnapshot(createDurableMemoryFixture(recordCount));
}

function reinforceTransition(record, authority = "verify-22") {
  return applyMemoryCommand(
    record,
    {
      type: "reinforce",
      expectedRevision: record.revision,
      confidenceDelta: 0.01,
      authority,
      at: AT,
    },
    { clock: CLOCK },
  );
}

function manifestDigestOf() {
  const manifest = JSON.parse(readFileSync(filePath, "utf8"));
  return manifest.digest;
}

/**
 * Throws on the Nth call to fs.fsyncSync. Returns the count of calls made so
 * the test can assert exactly how many directory syncs occurred, proving the
 * failure was raised at the intended stage (e.g. the post-rename directory
 * sync rather than an earlier shard sync).
 */
function failFsyncOnCall(callNumber) {
  const original = vi.spyOn(process, "getBuiltinModule");
  // spyOn on getBuiltinModule is not reliable for ESM default import binding;
  // instead stub the node:fs module binding used by the importers.
  let calls = 0;
  vi.stubModule?.("node:fs", () => {
    const real = original.getMockImplementation();
    void real;
    return {};
  });
  void calls;
  throw new Error("placeholder");
}

describe("Memory post-publish failure semantics (SegmentedMemoryPort)", () => {
  it("positive: a normal commit persists and is readable on reopen", async () => {
    const { record } = await seedAuthorityWith(1);
    const transition = reinforceTransition(record);
    const port = new SegmentedMemoryPort({ filePath });
    const committed = await port.commit(transition, record.revision);
    expect(committed.ok).toBe(true);
    expect(committed.storeRevision).toBe(2);

    const reopened = new SegmentedMemoryPort({ filePath });
    const read = await reopened.read(record.memoryId);
    expect(read).not.toBeNull();
    expect(read.revision).toBe(2);
    expect(read.digest).toBe(transition.record.digest);
  });

  it("post-publish fsync failure: error declares committed and reopen reads the new state", async () => {
    const { record } = await seedAuthorityWith(1);
    const transition = reinforceTransition(record);

    const calls = [];
    const originalFsync = process.getBuiltinModule("node:fs").fsyncSync;
    const stub = vi.stubModule?.;
    void stub;
    // Replace fs.fsyncSync so that the fsync of the manifest's parent
    // directory (the first directory-level fsync after the shard fsyncs)
    // throws, i.e. strictly after renameSync has published the manifest.
    let fsyncIndex = 0;
    const realModule = await import("node:fs");
    const descriptor = Object.getOwnPropertyDescriptor(realModule, "fsyncSync");
    if (descriptor) Object.defineProperty(realModule, "fsyncSync", {
      value: (fd) => {
        fsyncIndex += 1;
        calls.push(fsyncIndex);
        throw Object.assign(new Error("injected directory fsync failure"), {
          code: "EIO",
        });
      },
    });
    const port = new SegmentedMemoryPort({ filePath });

    let failure;
    try {
      await port.commit(transition, record.revision);
    } catch (error) {
      failure = error;
    }
    // Restore the real fsyncSync before reopening.
    Object.defineProperty(realModule, "fsyncSync", descriptor);

    expect(failure).toBeInstanceOf(Error);
    expect(failure.code).toBe("CONTEXT_MEMORY_COMMIT_PUBLISHED");
    expect(failure.committed).toBe(true);
    expect(failure.cleanupComplete).toBe(false);
    expect(failure.storeRevision).toBe(2);
    expect(calls.length).toBeGreaterThan(0);

    const reopened = new SegmentedMemoryPort({ filePath });
    const read = await reopened.read(record.memoryId);
    expect(read).not.toBeNull();
    expect(read.revision).toBe(2);
    expect(read.digest).toBe(transition.record.digest);
    expect(await reopened.getRevision()).toBe(2);
  });

  it("pre-publish fsync failure: error is NOT declared committed and reopen reads the old state", async () => {
    const { record } = await seedAuthorityWith(1);
    const transition = reinforceTransition(record);
    const digestBefore = manifestDigestOf();

    // Fail on the very first fsyncSync: the shard write, which happens before
    // the manifest rename, so `published` is still false.
    let fsyncCalls = 0;
    const realModule = await import("node:fs");
    const descriptor = Object.getOwnPropertyDescriptor(realModule, "fsyncSync");
    Object.defineProperty(realModule, "fsyncSync", {
      value: () => {
        fsyncCalls += 1;
        throw Object.assign(new Error("injected shard fsync failure"), {
          code: "EIO",
        });
      },
    });
    const port = new SegmentedMemoryPort({ filePath });

    let failure;
    try {
      await port.commit(transition, record.revision);
    } catch (error) {
      failure = error;
    }
    Object.defineProperty(realModule, "fsyncSync", descriptor);

    expect(failure).toBeInstanceOf(Error);
    expect(failure.code).toBe("EIO");
    expect(failure.committed).toBeUndefined();
    expect(fsyncCalls).toBeGreaterThan(0);

    const reopened = new SegmentedMemoryPort({ filePath });
    expect(await reopened.getRevision()).toBe(1);
    const read = await reopened.read(record.memoryId);
    expect(read.revision).toBe(1);
    expect(manifestDigestOf()).toBe(digestBefore);
  });

  it("after a committed publish, a stale CAS fails and the reopen revision is authoritative", async () => {
    const { record } = await seedAuthorityWith(1);
    const transition = reinforceTransition(record);
    const port = new SegmentedMemoryPort({ filePath });
    await port.commit(transition, record.revision);

    // A concurrent writer using the pre-commit revision must race out.
    const stale = await port.commit(transition, record.revision);
    expect(stale.ok).toBe(false);
    expect(stale.currentRevision).toBe(2);
    expect(stale.storeRevision).toBe(2);
    expect(await port.getRevision()).toBe(2);
  });

  it("positive: importSnapshot succeeds and reopen reads the imported record", async () => {
    const state = createDurableMemoryFixture(1);
    const port = seedEmptyAuthority();
    const imported = await port.importSnapshot(state);
    expect(imported.ok).toBe(true);
    expect(imported.storeRevision).toBe(state.storeRevision);
    expect(imported.recordCount).toBe(1);

    const reopened = new SegmentedMemoryPort({ filePath });
    const record = await reopened.read(Object.keys(state.records)[0]);
    expect(record).not.toBeNull();
    expect(record.digest).toBe(
      state.records[Object.keys(state.records)[0]].digest,
    );
  });

  it("putReconciliation post-publish fsync failure is committed and readable on reopen", async () => {
    const { record } = await seedAuthorityWith(1);
    const requestId = `verify-22-recon-${record.memoryId}`;
    const reconciliation = {
      requestId,
      memoryId: record.memoryId,
      storeRevision: 1,
      mode: "completed",
      at: AT,
      digest: stateDigest({ schema: "verify-22" }),
    };

    let fsyncIndex = 0;
    const realModule = await import("node:fs");
    const descriptor = Object.getOwnPropertyDescriptor(realModule, "fsyncSync");
    Object.defineProperty(realModule, "fsyncSync", {
      value: () => {
        fsyncIndex += 1;
        throw Object.assign(new Error("injected directory fsync failure"), {
          code: "EIO",
        });
      },
    });
    const port = new SegmentedMemoryPort({ filePath });

    let failure;
    try {
      await port.putReconciliation(reconciliation);
    } catch (error) {
      failure = error;
    }
    Object.defineProperty(realModule, "fsyncSync", descriptor);

    expect(failure).toBeInstanceOf(Error);
    expect(failure.code).toBe("CONTEXT_MEMORY_COMMIT_PUBLISHED");
    expect(failure.committed).toBe(true);
    expect(fsyncIndex).toBeGreaterThan(0);

    const reopened = new SegmentedMemoryPort({ filePath });
    const stored = await reopened.getReconciliation(requestId);
    expect(stored).not.toBeNull();
    expect(await reopened.getRevision()).toBe(2);
  });
});

